// The action atlas (2026-11-16): every thing a person can do on the network, in one routed map.
//
// Two layers:
//   inventory.json  GENERATED by scripts/atlas-inventory.mts: every write *host* in the repo
//                   (a server action export, a write API route handler, a raw SQL write site).
//                   Never hand-edited; regenerate it.
//   areas/*.ts      CURATED: capabilities. One capability = one thing a person (or the system) does,
//                   e.g. "publish a post". It claims the hosts that perform it. Six apps' copies of
//                   the same meeting action are one capability with six hosts.
//
// scripts/check-atlas.mts holds the two together: every inventory key must be claimed by exactly one
// capability host or listed in an area's `ignored`, and no claimed key may be missing from the
// inventory. scripts/atlas-reports.mts writes coverage, drift and confirm-wording waves.
//
// Plan: docs/open/mcp-foundations/DOCK_RAILS_PLAN.md (L1, L2, D-13, D-16).

/**
 * A host key names one write site, repo-relative, stable across line moves:
 *   sa:<repo path>#<export>       an export of a "use server" file (default export: #default;
 *                                 inline "use server" inside a function: #<outer export>/<fn>)
 *   api:<repo path>#<METHOD>      a route.ts handler: POST | PUT | PATCH | DELETE
 *   sql:<repo path>#<function>    a raw INSERT/UPDATE/DELETE inside a named function (#<module> at top level)
 * e.g. sa:apps/arts-collective/src/lib/channel/actions.ts#acceptSuggestion
 *      api:apps/arts-collective/src/app/api/actions/[id]/route.ts#POST
 */
export type HostKey = `${'sa' | 'api' | 'sql'}:${string}#${string}`;

/** What the inventory generator records per host. */
export interface InventoryHost {
  key: HostKey;
  kind: 'sa' | 'api' | 'sql';
  app: string; // apps/<name> or packages/<name> directory name
  file: string; // repo-relative
  symbol: string;
  line: number; // informational only; not part of the key
  /** Workspace imports used by the file (@elkdonis/services, @elkdonis/hub, ...), for grouping. */
  imports: string[];
  /** Service-like functions the symbol's body calls from those imports, when resolvable. */
  calls: string[];
  /** Calls a registry door (runAction / performAction / performHubAction / performSiteChannelAction). */
  registry: boolean;
  /** Raw SQL write statements found in the symbol's body. */
  rawSql: boolean;
}

export type Actor = 'visitor' | 'person' | 'member' | 'guide' | 'owner' | 'operator' | 'admin' | 'system';
export type Risk =
  | 'money' // charges, payouts, Stripe: the dock only ever links, never runs
  | 'irreversible' // deletes, removes, sends that cannot be undone
  | 'public' // makes something visible to the public or other people
  | 'emails' // sends email or notifications
  | 'others' // changes another person's data or membership
  | 'none';

/** Confirm-card wording. Justin approves wording in waves (D-16); only `approved` text reaches a live dock. */
export interface Wording {
  text: string; // e.g. "Publish “{title}” on {org}'s site? Visitors will see it."
  status: 'draft' | 'proposed' | 'approved' | 'changed';
  wave?: number; // the review wave it went out in (atlas/reports/wording-wave-NN.md)
  note?: string; // Justin's note, or the open question
}

/** Where the control lives, so the dock can take a person there (L3). */
export interface Address {
  app: string; // which app serves it (arts-collective, sunjay, ...)
  path: string; // path template: /hub/sites/{org}/pages, /studio/{slug}
  anchor?: string; // data-eac-anchor value to outline (planned; usually the capability id)
  surface?: string; // popup address: thread:{id}, profile, ...
  how?: string; // one line: "the Publish button in the post's pin bar"
}

export interface Host {
  key: HostKey;
  address?: Address;
  /** Service functions this host calls; differing lists across hosts = drift. */
  service?: string[];
  /**
   * When one host serves several entries (a dispatcher: runTenantHubAction, api/lms/[action]), each claim names the
   * case it covers, e.g. the action id it switches on. (key, case) is unique; a key claimed with cases is never also
   * claimed whole. Added 2026-11-16 (lead), from agent B open question 1.
   */
  case?: string;
  note?: string;
}

export interface Capability {
  id: string; // kebab-case, stable; equals the registry entry id once it has one
  area: string; // e.g. hub.people, studio.pieces, channel.plan, learn
  label: string; // short verb phrase: "Publish a post"
  does: string; // one or two plain sentences
  class: 'person' | 'internal' | 'admin' | 'system'; // person = a candidate rail step
  actors: Actor[];
  scope: 'person' | 'org' | 'thread' | 'channel' | 'series' | 'other';
  hosts: Host[];
  /** Registry entry id when covered; null when it should get one; undefined when it should not. */
  entry?: string | null;
  /** How we know it's done: an existing CHECKS id, or a one-line description of the query. */
  status?: string;
  risk: Risk[];
  confirm?: Wording; // person-class rows only
  inputs?: string; // short: "title, body, feed"
  /** Homogenising (L1): how hosts differ, and the one path they should converge on. */
  drift?: string;
  canonical?: string; // the service function / host that should be the single path
  open?: string; // a question for Justin or the next session
  verified: string; // "2026-11-16 read" — date + how it was checked
}

/** Inventory keys an area deliberately does not map, with why (reads mislabelled as writes, dev tools, dead code). */
export interface Ignored {
  key: HostKey;
  why: string;
}

export interface Area {
  capabilities: Capability[];
  ignored: Ignored[];
}
